{
  "command": "cp core.cuh core.cuh.bak && cp helio.cu helio.cu.bak && python3 - <<'EOF'
p='core.cuh'
s=open(p).read()
s=s.replace('#define NV 11\n#define ETA_DE 1e-3f\nenum { RHO = 0, MX, MY, MZ, EN, BX, BY, BZ, PSI, SC, ENT };','#ifndef NTR\n#define NTR 1\n#endif\n#define NV (10 + NTR)\n#define ETA_DE 1e-3f\nenum { RHO = 0, MX, MY, MZ, EN, BX, BY, BZ, PSI, ENT, SC };')
s=s.replace('''    f[9] = F7[0] * (F7[0] >= 0.f ? qL[9] : qR[9]);
    f[10] = F7[0] * (F7[0] >= 0.f ? qL[10] : qR[10]);
}''','''    const float* qu = F7[0] >= 0.f ? qL : qR;
    for (int m = ENT; m < NV; m++) f[m] = F7[0] * qu[m];
}''')
s=s.replace('''    q[5] = U[BX]; q[6] = U[BY]; q[7] = U[BZ]; q[8] = U[PSI]; q[9] = U[SC] * id; q[10] = p * powf(d, -gam);
}''','''    q[5] = U[BX]; q[6] = U[BY]; q[7] = U[BZ]; q[8] = U[PSI]; q[ENT] = p * powf(d, -gam);
    for (int m = SC; m < NV; m++) q[m] = U[m] * id;
}''')
s=s.replace('''    U[BX] = q[5]; U[BY] = q[6]; U[BZ] = q[7]; U[PSI] = q[8]; U[SC] = q[0] * q[9];
    U[ENT] = q[4] * powf(q[0], 1.f - gam);
}''','''    U[BX] = q[5]; U[BY] = q[6]; U[BZ] = q[7]; U[PSI] = q[8];
    U[ENT] = q[4] * powf(q[0], 1.f - gam);
    for (int m = SC; m < NV; m++) U[m] = q[0] * q[m];
}''')
open(p,'w').write(s)

p='helio.cu'
s=open(p).read()
s=s.replace('''    F[PSI * nf + id] = f[8] * A;
    F[SC * nf + id] = f[9] * A;
    F[ENT * nf + id] = f[10] * A;
}''','''    F[PSI * nf + id] = f[8] * A;
    for (int m = ENT; m < NV; m++) F[m * nf + id] = f[m] * A;
}''')
s=s.replace('''__device__ inline void bnd_state(float r, float th, float ph, const float* o, float* u)
{''','''__device__ inline void bnd_state(float r, float th, float ph, const float* o, float* u, float lam, float tau)
{''')
s=s.replace('''    float q[NV] = {d, vr * er[0], vr * er[1], vr * er[2], p, br * er[0] + bp * ep[0], br * er[1] + bp * ep[1], br * er[2], 0.f, o[4]};
    prim2cons(q, P.gam, u);''','''    float q[NV] = {d, vr * er[0], vr * er[1], vr * er[2], p, br * er[0] + bp * ep[0], br * er[1] + bp * ep[1], br * er[2], 0.f, 0.f};
    q[SC] = o[4];
#if NTR > 1
    q[SC + 1] = cosf(lam * 0.01745329252f);
    q[SC + 2] = sinf(lam * 0.01745329252f);
    q[SC + 3] = 90.f - th * 57.29577951f;
    q[SC + 4] = tau;
#endif
    prim2cons(q, P.gam, u);''')
s=s.replace('''        bnd_state(rc[g], th, ph, o, u);''','''        bnd_state(rc[g], th, ph, o, u, lon, tau - (P.rin - rc[g]) / fmaxf(o[0] / 100.f, 0.5f));''')
s=s.replace('''    bnd_state(r, th, ph, o, u);
    float q[NV];''','''    bnd_state(r, th, ph, o, u, ph * 57.29577951f - lonshift, -1.f);
    float q[NV];''')
s=s.replace('''        w[8] = q[8];
        w[9] = q[9];''','''        w[8] = q[8];
        for (int m = ENT; m < NV; m++) w[m] = q[m];''')
s=s.replace('''    float q[NV] = {d, vx, vy, vz, p, bx, by, bz, 0.f, 0.f};''','''    float q[NV] = {d, vx, vy, vz, p, bx, by, bz, 0.f, 0.f};
    for (int m = SC; m < NV; m++) q[m] = 0.f;''')
s=s.replace('''    for (int m = 0; m < 10; m++) out[m] = nanf("");''','''    for (int m = 0; m < 9 + NTR; m++) out[m] = nanf("");''')
s=s.replace('''    out[8] = acc[9];
    out[9] = r;''','''    out[8] = acc[SC];
    out[9] = r;
    for (int m = 1; m < NTR; m++) out[9 + m] = acc[SC + m];''')
s=s.replace('''    float o[10];
    interp(U, pos[3 * id], pos[3 * id + 1], pos[3 * id + 2], o);
    o[5] *= b0; o[6] *= b0; o[7] *= b0;
    for (int m = 0; m < 10; m++) out[id * 10 + m] = o[m];''','''    float o[9 + NTR];
    interp(U, pos[3 * id], pos[3 * id + 1], pos[3 * id + 2], o);
    o[5] *= b0; o[6] *= b0; o[7] *= b0;
    for (int m = 0; m < 9 + NTR; m++) out[id * (9 + NTR) + m] = o[m];''')
s=s.replace('''    float o[10];
    interp(U, R, th, ph, o);''','''    float o[9 + NTR];
    interp(U, R, th, ph, o);''')
s=s.replace('''    out[8 * n + id] = q[9];''','''    out[8 * n + id] = q[SC];''')
s=s.replace('''    if (tr.nb) { CK(cudaMalloc(&d_pos, tr.nb * 3 * 4)); CK(cudaMalloc(&d_pout, tr.nb * 10 * 4)); }''','''    if (tr.nb) { CK(cudaMalloc(&d_pos, tr.nb * 3 * 4)); CK(cudaMalloc(&d_pout, tr.nb * (9 + NTR) * 4)); }''')
s=s.replace('''        int h[2] = {tr.nb, 10};''','''        int h[2] = {tr.nb, 9 + NTR};''')
s=s.replace('''        std::vector<float> o(tr.nb * 10);''','''        std::vector<float> o(tr.nb * (9 + NTR));''')
open(p,'w').write(s)
EOF
grep -n "k_bc_inner(float" helio.cu; grep -n "float tau" helio.cu | head; sed -i 's/^all: helio test1d test1d_d$/all: helio helio_trace test1d test1d_d/' Makefile; cat >> Makefile <<'EOF'
helio_trace: helio.cu core.cuh
	$(NVCC) $(FLAGS) -DNTR=5 -o helio_trace helio.cu
EOF
make helio helio_trace test1d test1d_d 2>&1 | grep -i -E "error" ; ls -la helio helio_trace | awk '{print $6,$7,$8,$9}'",
  "description": "Refactor tracers into a compile-time count and build trace variant",
  "timeout": 600000
}

