print(s.iloc[::6][['utc','n','v','flux','src_lon','src_lat','t_emit']].assign(t_emit=lambda d:(I.T_REF+pd.to_timedelta(d.t_emit,unit='s')).dt.strftime('%m-%d %H'),utc=lambda d:d.utc.dt.strftime('%m-%d %H:%M')).to_string(index=False))
"",
